CREATE OR REPLACE FUNCTION "bricx"."sod_conflict"() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog
  AS $$
DECLARE
  counterparts text[];
BEGIN
  counterparts := CASE NEW.record_type || '.' || NEW.action
    WHEN 'field.attendance.approve' THEN ARRAY['field.attendance.create']
    WHEN 'field.attendance.create' THEN ARRAY['field.attendance.approve']
    WHEN 'field.dailylog.approve' THEN ARRAY['field.dailylog.create', 'field.dailylog.update']
    WHEN 'field.dailylog.create' THEN ARRAY['field.dailylog.approve']
    WHEN 'field.dailylog.update' THEN ARRAY['field.dailylog.approve']
    WHEN 'finance.budget.approve' THEN ARRAY['finance.budget.create', 'finance.budget.update']
    WHEN 'finance.budget.create' THEN ARRAY['finance.budget.approve']
    WHEN 'finance.budget.update' THEN ARRAY['finance.budget.approve']
    WHEN 'finance.change_order.approve' THEN ARRAY['finance.change_order.create']
    WHEN 'finance.change_order.create' THEN ARRAY['finance.change_order.approve']
    WHEN 'finance.expenditure.approve' THEN ARRAY['finance.expenditure.create']
    WHEN 'finance.expenditure.create' THEN ARRAY['finance.expenditure.approve']
    WHEN 'finance.payment.approve' THEN ARRAY['finance.payment.request']
    WHEN 'finance.payment.record' THEN ARRAY['finance.reconciliation.create']
    WHEN 'finance.payment.request' THEN ARRAY['finance.payment.approve']
    WHEN 'finance.reconciliation.create' THEN ARRAY['finance.payment.record']
    WHEN 'supply.goods_receipt.create' THEN ARRAY['supply.purchase_order.create']
    WHEN 'supply.material_request.approve' THEN ARRAY['supply.material_request.create', 'supply.material_request.update']
    WHEN 'supply.material_request.create' THEN ARRAY['supply.material_request.approve']
    WHEN 'supply.material_request.update' THEN ARRAY['supply.material_request.approve']
    WHEN 'supply.purchase_order.approve' THEN ARRAY['supply.purchase_order.create']
    WHEN 'supply.purchase_order.create' THEN ARRAY['supply.goods_receipt.create', 'supply.purchase_order.approve']
    ELSE NULL
  END;
  IF counterparts IS NULL THEN
