    SELECT 1 FROM bricx.sod_actions s
    WHERE s.org_id = NEW.org_id
      AND s.chain_id = NEW.chain_id
      AND s.actor_id = NEW.actor_id
      AND (s.record_type || '.' || s.action) = ANY (counterparts)
